INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Git nur für Softwareentwickler nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Projekte wie Dokumentation"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Git?', 3, '[{"text": "Versionskontrolle", "correct": true, "because": "Änderungen nachverfolgen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht primär"}, {"text": "UI-Gestaltung", "correct": false, "because": "Kein Designfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Git?', 5, '[{"text": "Commits", "correct": true, "because": "Speichern Änderungen"}, {"text": "Branches", "correct": true, "because": "Parallelentwicklung ermöglichen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Kein Git-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Commits speichern Änderungsstände. b) Branches sind nur für Teams nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Branches auch für Einzelarbeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Git?', 4, '[{"text": "Commit-Nachrichten", "correct": false, "because": "Dokumentieren Änderungen"}, {"text": "Branch-Strategie", "correct": false, "because": "Organisiert Entwicklung"}, {"text": "UI-Optik", "correct": true, "because": "Kein Git-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Git auch ohne Branches funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Nur main-Branch möglich"}, {"text": "Nein", "correct": false, "because": "Branches optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl nutze ich für einen neuen Commit?', 3, '[{"text": "git commit", "correct": true, "because": "Speichert Änderungen"}, {"text": "git branch", "correct": false, "because": "Erstellt Branch"}, {"text": "git merge", "correct": false, "because": "Führt Branches zusammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen verbessern die Nutzung von Git?', 5, '[{"text": "Merging", "correct": true, "because": "Kombiniert Branches"}, {"text": "Staging", "correct": true, "because": "Bereitet Änderungen vor"}, {"text": "Datenfluss", "correct": false, "because": "Kein Git-Fokus"}, {"text": "UI-Rendering", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Git erlaubt parallele Entwicklung. b) Merges sind immer konfliktfrei. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konflikte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Nutzung von Git?', 4, '[{"text": "Commits", "correct": false, "because": "Speichern Änderungen"}, {"text": "Repository", "correct": false, "because": "Basis der Versionierung"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Git-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Branch in Git immer notwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Arbeit auf main möglich"}, {"text": "Ja", "correct": false, "because": "Optional nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle nutze ich für parallele Entwicklung?', 4, '[{"text": "git branch", "correct": true, "because": "Erstellt neuen Branch"}, {"text": "git merge", "correct": true, "because": "Führt Branches zusammen"}, {"text": "git format", "correct": false, "because": "Kein Git-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Git ohne Commits nutzlos ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Commits sind Kernfunktion"}, {"text": "Nein", "correct": false, "because": "Ohne Commits keine Versionierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von Git?', 3, '[{"text": "Klarheit der Commits", "correct": true, "because": "Fördert Nachvollziehbarkeit"}, {"text": "Schnelle Merges", "correct": false, "because": "Korrektheit zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Git unterstützt Branches. b) Merges sind immer automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Merges können Konflikte haben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Git?', 5, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Änderungen dokumentiert"}, {"text": "Zusammenarbeit", "correct": true, "because": "Branches und Merges"}, {"text": "Datenkompression", "correct": false, "because": "Nicht primär"}, {"text": "UI-Animation", "correct": false, "because": "Kein Git-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Git unwichtig?', 3, '[{"text": "Commit-Historie", "correct": false, "because": "Kern der Versionierung"}, {"text": "Branch-Management", "correct": false, "because": "Fördert Zusammenarbeit"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Git-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich in Git ohne Merges arbeiten?', 3, '[{"text": "Ja", "correct": true, "because": "Nur main-Branch möglich"}, {"text": "Nein", "correct": false, "because": "Merges optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Git für Einzelentwickler nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Auch Solo-Versionierung hilft"}, {"text": "Nein", "correct": false, "because": "Nicht nur für Teams"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um einen neuen Branch zu erstellen?', 4, '[{"text": "git branch", "correct": true, "because": "Erstellt neuen Branch"}, {"text": "git commit", "correct": false, "because": "Speichert Änderungen"}, {"text": "git push", "correct": false, "because": "Sendet an Remote"}]');
